struct autologin_profile * autologin_find_profile ( char * identifier ) { int i ; struct autologin_profile * default_profile = NULL ; if ( strlen ( identifier ) == 0 ) { return in ; } for ( i = 0 ; i < AUTOLOGIN_MAXPROFILES ; ++ i ) { if ( login_profiles [ i ] . inuse && strcasecmp ( identifier , login_profiles [ i ] . identifier ) == 0 ) { return & login_profiles [ i ] ; } if ( login_profiles [ i ] . inuse && strcasecmp ( "default" , login_profiles [ i ] . identifier ) == 0 ) { default_profile = & login_profiles [ i ] ; } } return default_profile ; } 